from collections import deque
class Solution:
    def maximumMinutes(self, grid):
        m, n = len(grid), len(grid[0])
        INF = float('inf')
        f = [[INF] * n for _ in range(m)]
        q = deque()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    f[i][j] = 0
                    q.append((i, j))
        D = ((1,0),(-1,0),(0,1),(0,-1))
        while q:
            i, j = q.popleft()
            for di, dj in D:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 0 and f[ni][nj] == INF:
                    f[ni][nj] = f[i][j] + 1
                    q.append((ni, nj))
        def ok(t):
            if t >= f[0][0]:
                return False
            seen = [[False] * n for _ in range(m)]
            seen[0][0] = True
            q = deque([(0, 0, t)])
            while q:
                i, j, d = q.popleft()
                for di, dj in D:
                    ni, nj = i + di, j + dj
                    nd = d + 1
                    if not (0 <= ni < m and 0 <= nj < n) or grid[ni][nj] != 0 or seen[ni][nj]:
                        continue
                    if ni == m - 1 and nj == n - 1:
                        if nd <= f[ni][nj]:
                            return True
                    elif nd < f[ni][nj]:
                        seen[ni][nj] = True
                        q.append((ni, nj, nd))
            return False
        if not ok(0):
            return -1
        lo, hi = 0, m * n
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return 10 ** 9 if lo >= m * n else lo

