class Solution {
public:
    int maximumMinutes(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> f(m, vector<int>(n, INT_MAX));
        queue<pair<int,int>> q;
        int dr[] = {1,-1,0,0}, dc[] = {0,0,1,-1};
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1) { f[i][j] = 0; q.push({i,j}); }
        while (!q.empty()) {
            auto [i, j] = q.front(); q.pop();
            for (int d = 0; d < 4; d++) {
                int ni = i + dr[d], nj = j + dc[d];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] == 0 && f[ni][nj] == INT_MAX) {
                    f[ni][nj] = f[i][j] + 1;
                    q.push({ni, nj});
                }
            }
        }
        auto ok = [&](int t) -> bool {
            if (t >= f[0][0]) return false;
            vector<vector<char>> seen(m, vector<char>(n, 0));
            queue<array<int,3>> pq;
            pq.push({0, 0, t});
            seen[0][0] = 1;
            while (!pq.empty()) {
                auto [i, j, d] = pq.front(); pq.pop();
                for (int k = 0; k < 4; k++) {
                    int ni = i + dr[k], nj = j + dc[k], nd = d + 1;
                    if (ni < 0 || ni >= m || nj < 0 || nj >= n || grid[ni][nj] != 0 || seen[ni][nj]) continue;
                    if (ni == m - 1 && nj == n - 1) {
                        if (nd <= f[ni][nj]) return true;
                    } else if (nd < f[ni][nj]) {
                        seen[ni][nj] = 1;
                        pq.push({ni, nj, nd});
                    }
                }
            }
            return false;
        };
        if (!ok(0)) return -1;
        int lo = 0, hi = m * n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid; else hi = mid - 1;
        }
        return lo >= m * n ? 1000000000 : lo;
    }
};

