import java.util.*;
class Solution {
    public int maximumMinutes(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] f = new int[m][n];
        for (int[] row : f) Arrays.fill(row, Integer.MAX_VALUE);
        ArrayDeque<int[]> q = new ArrayDeque<>();
        int[] dr = {1,-1,0,0}, dc = {0,0,1,-1};
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1) { f[i][j] = 0; q.add(new int[]{i, j}); }
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int d = 0; d < 4; d++) {
                int ni = cur[0] + dr[d], nj = cur[1] + dc[d];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] == 0 && f[ni][nj] == Integer.MAX_VALUE) {
                    f[ni][nj] = f[cur[0]][cur[1]] + 1;
                    q.add(new int[]{ni, nj});
                }
            }
        }
        java.util.function.IntPredicate ok = t -> {
            if (t >= f[0][0]) return false;
            boolean[][] seen = new boolean[m][n];
            ArrayDeque<int[]> pq = new ArrayDeque<>();
            pq.add(new int[]{0, 0, t});
            seen[0][0] = true;
            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                for (int k = 0; k < 4; k++) {
                    int ni = cur[0] + dr[k], nj = cur[1] + dc[k], nd = cur[2] + 1;
                    if (ni < 0 || ni >= m || nj < 0 || nj >= n || grid[ni][nj] != 0 || seen[ni][nj]) continue;
                    if (ni == m - 1 && nj == n - 1) {
                        if (nd <= f[ni][nj]) return true;
                    } else if (nd < f[ni][nj]) {
                        seen[ni][nj] = true;
                        pq.add(new int[]{ni, nj, nd});
                    }
                }
            }
            return false;
        };
        if (!ok.test(0)) return -1;
        int lo = 0, hi = m * n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (ok.test(mid)) lo = mid; else hi = mid - 1;
        }
        return lo >= m * n ? 1000000000 : lo;
    }
}

